const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(route,label)=>`<button class="chip" data-route="${esc(route)}">${esc(label)} →</button>`;
const options=values=>values.map(v=>`<option>${esc(v)}</option>`).join('');
const active=c=>![...Modelo.cerrados,'Aprobada'].includes(c.estado);
const modal=$('modal');
let state,p=Modelo.perfiles[0],bootError='';
try{state=Modelo.leer();localStorage.setItem(Modelo.clave,JSON.stringify(state));p=Modelo.persona(localStorage.getItem('perfil-demo'))||p;}catch(e){state=Modelo.inicial();bootError='No se pudieron recuperar o guardar los datos. '+e.message;}
const gestor=()=>p.rol==='gestor';
const ownCases=()=>state.casos.filter(c=>gestor()||c.persona===p.id);
document.querySelector('main').insertAdjacentHTML('afterbegin','<p class="demo-note">Demo con datos ficticios · Los perfiles comparten datos en este navegador. Reglas pendientes de validación por Prebel.</p><p id="notice" class="status" role="status" hidden></p><section id="staff" hidden></section>');
document.querySelector('.layout').insertAdjacentHTML('afterend','<section id="pending"></section>');
document.querySelector('footer').insertAdjacentHTML('beforeend','<button class="chip" id="reset">Restablecer demo</button>');
document.querySelector('.search small').textContent='Consulta guiada';
document.querySelector('.search').insertAdjacentHTML('beforeend','<p class="muted">Sugerencias por tema y perfil. Respuestas de demostración.</p>');
$('faq-list').insertAdjacentHTML('beforebegin','<label for="faq-filter">Filtrar por tema</label><select id="faq-filter">'+options(['Todos','Vacaciones','Nómina','Certificados','Atención','SST'])+'</select>');
function notice(text){$('notice').hidden=false;$('notice').textContent=text;}
function go(route){if(location.hash==='#'+route)routePage();else location.hash=route;}
function show(title,body){$('detail').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<p id="form-error" role="alert" class="error"></p>`;modal.setAttribute('aria-labelledby','dialog-title');if(!modal.open)modal.showModal();}
async function mutate(change,done){const button=document.activeElement;if(button?.tagName==='BUTTON')button.disabled=true;try{state=await Modelo.guardar(change);render();if(done)done();}catch(e){if($('form-error'))$('form-error').textContent=e.message;else notice(e.message);}finally{if(button?.tagName==='BUTTON')button.disabled=false;}}
function cards(cases){return cases.length?cases.map(c=>`<button class="case-card" data-route="caso/${esc(c.id)}"><span><small>${esc(c.id)} · ${esc(c.tema)}${c.ejemplo?' · Ejemplo inicial':''}</small><b>${esc(c.asunto)}</b><span>${esc(Modelo.persona(c.persona)?.nombre)}</span></span><span class="badge">${esc(c.estado)}</span></button>`).join(''):'<p class="muted">No hay casos para este filtro.</p>';}
function render(){
  $('perfil').innerHTML=Modelo.perfiles.map(person=>`<option value="${person.id}">${esc(person.nombre)} · ${person.rol==='gestor'?'Gestión Humana':person.area==='admin'?'Administración':'Producción'}</option>`).join('');$('perfil').value=p.id;
  $('nombre').textContent=p.nombre.split(' ')[0];$('puesto').textContent=p.cargo+' · '+catalogo.areas.find(a=>a.id===p.area).nombre;
  document.querySelector('.hero small').textContent=gestor()?'CENTRO DE ATENCIÓN':'PORTAL DEL COLABORADOR';document.querySelector('.layout').hidden=gestor();$('services').parentElement.hidden=gestor();$('staff').hidden=!gestor();
  if(gestor())$('staff').innerHTML='<h2>Una atención que continúa</h2><p>Responde a los colaboradores y mejora las respuestas que necesitan ayuda.</p><div class="metrics"><article><strong>'+state.casos.filter(active).length+'</strong><span>Casos por atender</span></article><article><strong>'+state.casos.filter(c=>!c.ejemplo).length+'</strong><span>Solicitudes creadas en la demo</span></article><article><strong>'+state.feedback.filter(f=>f.util).length+' / '+state.feedback.length+'</strong><span>Valoraciones útiles / recibidas</span></article></div>'+action('solicitudes','Abrir bandeja')+action('contenidos','Gestionar conocimiento');else $('balance').textContent=Modelo.saldo(state,p.id);
  $('pending').innerHTML='<h2>'+(gestor()?'Casos que necesitan atención':'Tu actividad reciente')+'</h2>'+cards(ownCases().filter(active).slice(0,3));
  $('services').innerHTML=[['vacaciones','Vacaciones','Planea tu descanso','☼'],['nomina','Nómina','Revisa y descarga tu comprobante','▤'],['certificado','Certificados','Con o sin salario','✎'],['ayuda','Solicitar ayuda','Consulta al equipo responsable','◷']].map(([id,title,desc,icon])=>`<a class="service" href="#${id}"><em aria-hidden="true">${icon}</em><b>${title}</b><span>${desc}</span></a>`).join('');renderFAQ();suggestions();
}
function renderFAQ(){const list=state.articulos.filter(a=>Modelo.visible(a,p)&&($('faq-filter').value==='Todos'||a.tema===$('faq-filter').value));$('faq-list').innerHTML=list.map(a=>`<details><summary>${esc(a.titulo)}</summary><p>${esc(a.respuesta)}</p><small>${esc(a.responsable)} · Versión ${a.version}</small>${action('articulo/'+a.id,'Ver pasos y requisitos')}</details>`).join('')||'<p>No hay preguntas para este tema.</p>';}
function suggestions(){const q=$('query').value.trim();if(/ausentar|faltar/i.test(q)){$('matches').innerHTML='<p>¿Qué tipo de ausencia quieres consultar?</p>'+action('articulo/vacaciones','Vacaciones')+action('articulo/permiso','Permiso personal');return;}const results=q?Modelo.buscar(state,p,q):['saldo','proyeccion','nomina','certificado'].map(id=>state.articulos.find(a=>a.id===id)).filter(a=>Modelo.visible(a,p));$('matches').innerHTML=results.length?results.map(a=>action('articulo/'+a.id,a.titulo)).join(''):'<p>No encontré una respuesta publicada para esa consulta.</p>'+action('ayuda','Pedir orientación');}
function articleView(id){
  const a=state.articulos.find(a=>a.id===id&&Modelo.visible(a,p));if(!a)return show('Contenido no disponible','<p>No corresponde al perfil seleccionado.</p>');
  show(a.titulo,`<p class="answer">${esc(a.respuesta)}</p><div class="facts"><div><small>Responsable</small>${esc(a.responsable)}</div><div><small>Requisitos</small>${esc(a.requisitos)}</div></div><h3>Paso a paso</h3><ol>${a.pasos.split('\n').map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>${gestor()?'':action(a.accion+(a.accion==='ayuda'?'/'+a.id:''),a.etiqueta)}<details class="source"><summary>Fuente y vigencia del contenido</summary><p>${esc(a.fuente)}<br>Versión ${a.version} · Actualizado ${esc(a.actualizado)}<br>${esc(a.validacion)}<br>Tiempo de respuesta: ${esc(a.plazo)}<br>${esc(a.canal)}</p></details><div class="feedback"><p>¿Esta respuesta te ayudó?</p><button class="chip" id="useful">Sí, resolvió mi duda</button><button class="chip" id="not-useful">Necesito ayuda</button></div>`);
  const vote=util=>mutate(s=>{s.feedback=s.feedback.filter(f=>!(f.persona===p.id&&f.articulo===id&&f.version===a.version));s.feedback.push({persona:p.id,articulo:id,version:a.version,util,fecha:new Date().toISOString()});},()=>{if(util){$('useful').textContent='Gracias por tu valoración';$('useful').disabled=true;}else go((gestor()?'editar/':'ayuda/')+id);});$('useful').onclick=()=>vote(true);$('not-useful').onclick=()=>vote(false);
}
function helpView(id){if(gestor())return historyView();const a=state.articulos.find(a=>a.id===id&&Modelo.visible(a,p));show('Cuéntanos qué necesitas',`<p>El caso tendrá un número de seguimiento. Usa información ficticia.</p><form id="help"><label for="team">Equipo responsable</label><select id="team">${options(['Gestión Humana','Nómina','Contratación','SST'])}</select><label for="subject">Asunto</label><input id="subject" required maxlength="120" value="${esc(a?.titulo||$('query').value)}"><label for="message">Describe tu consulta</label><textarea id="message" required maxlength="1500" rows="4"></textarea><button class="primary">Enviar consulta</button></form>`);if(a)$('team').value=a.responsable;
  $('help').onsubmit=e=>{e.preventDefault();const data={tipo:'Consulta',tema:$('team').value,asunto:$('subject').value.trim(),mensaje:$('message').value.trim()};if(!data.asunto||!data.mensaje)return;let id;mutate(s=>{id=Modelo.crearCaso(s,p.id,data).id;},()=>go('caso/'+id));};}
function vacation(start='',end=''){if(gestor())return historyView();show('Planear vacaciones',`<p>Dispones de <b>${Modelo.saldo(state,p.id)} días</b>. La demo cuenta de lunes a viernes, incluidos festivos. El aprobador y las reglas deben validarse con Prebel.</p><form id="dates"><label for="start">Desde</label><input id="start" type="date" required min="${Modelo.fecha()}" value="${start}"><label for="end">Hasta</label><input id="end" type="date" required min="${start||Modelo.fecha()}" value="${end}"><button class="primary">Revisar solicitud</button></form>`);$('start').oninput=()=>{$('end').min=$('start').value;};
  $('dates').onsubmit=e=>{e.preventDefault();const data={tipo:'Vacaciones',tema:'Gestión Humana',asunto:'Solicitud de vacaciones',inicio:$('start').value,fin:$('end').value};try{Modelo.crearCaso(structuredClone(state),p.id,data);}catch(err){$('form-error').textContent=err.message;return;}
    show('Revisar solicitud',`<p>${esc(data.inicio)} — ${esc(data.fin)}</p><p class="status">${data.dias} días · Saldo restante: ${Modelo.saldo(state,p.id)-data.dias}</p><button id="edit-dates" class="chip">Editar fechas</button><button id="send" class="primary">Confirmar solicitud</button>`);$('edit-dates').onclick=()=>vacation(data.inicio,data.fin);$('send').onclick=()=>{let id;mutate(s=>{id=Modelo.crearCaso(s,p.id,data).id;},()=>go('caso/'+id));};};}
function forecast(){if(gestor())return historyView();show('Proyectar mi saldo','<p>Simulación: suma 1,25 días por mes y supone que no tomarás más vacaciones. Regla pendiente de validación.</p><label for="months">Meses por proyectar</label><select id="months">'+options([1,3,6,12])+'</select><p id="estimate" class="status" aria-live="polite"></p>'+action('vacaciones','Planear vacaciones'));const update=()=>{$('estimate').textContent='Saldo estimado: '+(Modelo.saldo(state,p.id)+Number($('months').value)*1.25).toLocaleString('es-CO')+' días';};$('months').onchange=update;update();}
const preview=d=>'<div class="document-preview"><small>Demostración · Datos ficticios</small><h3>'+esc(d.titulo)+'</h3>'+d.lineas.map(l=>'<p>'+esc(l)+'</p>').join('')+'<b>Sin validez laboral</b></div>';
function download(d,id){try{Documentos.pdf(d,id).save(id+'-demo.pdf');}catch(e){$('form-error').textContent='No se pudo crear el PDF: '+e.message;}}
function certificate(){if(gestor())return historyView();show('Certificado laboral','<label for="type">Información del certificado</label><select id="type">'+options(['Sin salario','Con salario'])+'</select><div id="preview"></div><button id="generate" class="primary">Generar certificado PDF</button>');const doc=()=>Documentos.certificado(p,$('type').selectedIndex===1);const update=()=>{$('preview').innerHTML=preview(doc());};$('type').onchange=update;update();$('generate').onclick=()=>{const documento=doc();let id;mutate(s=>{id=Modelo.crearCaso(s,p.id,{tipo:'Certificado laboral',tema:'Contratación',asunto:'Certificado laboral '+($('type').selectedIndex?'con':'sin')+' salario',documento}).id;},()=>go('caso/'+id));};}
function payroll(){if(gestor())return historyView();const now=new Date(),months=Array.from({length:3},(_,i)=>new Date(now.getFullYear(),now.getMonth()-1-i,1).toLocaleDateString('es-CO',{month:'long',year:'numeric'}));show('Comprobante de nómina','<label for="period">Período</label><select id="period">'+options(months)+'</select><div id="preview"></div><button id="download" class="primary">Descargar PDF</button>'+action('ayuda/revision','Solicitar revisión'));const doc=()=>Documentos.nomina(p,$('period').value,$('period').selectedIndex);const update=()=>{$('preview').innerHTML=preview(doc());};$('period').onchange=update;update();$('download').onclick=()=>download(doc(),'nomina-'+p.id+'-'+$('period').selectedIndex);}
function historyView(){show(gestor()?'Bandeja de atención':'Mis solicitudes','<div class="filters"><div><label for="case-state">Estado</label><select id="case-state">'+options(['Todos','Recibido','En atención','Esperando información','Aprobada','Devuelta','Resuelto','Cancelada'])+'</select></div><div><label for="case-team">Equipo</label><select id="case-team">'+options(['Todos','Gestión Humana','Nómina','Contratación','SST'])+'</select></div></div><div id="cases"></div>');const update=()=>{$('cases').innerHTML=cards(ownCases().filter(c=>($('case-state').value==='Todos'||c.estado===$('case-state').value)&&($('case-team').value==='Todos'||c.tema===$('case-team').value)));};$('case-state').onchange=update;$('case-team').onchange=update;update();}
function caseView(id){const c=ownCases().find(c=>c.id===id);if(!c)return show('Caso no disponible','<p>Este caso no corresponde al perfil seleccionado.</p>');show(c.asunto,`<p><b>${esc(c.id)}</b> · ${esc(c.tema)} · <span class="badge">${esc(c.estado)}</span></p>${c.ejemplo?'<p class="muted">Escenario inicial ficticio</p>':''}${c.tipo==='Vacaciones'?`<p>${esc(c.inicio)} — ${esc(c.fin)} · ${c.dias} días</p>`:''}${c.documento?preview(c.documento)+'<button class="primary" id="download">Descargar PDF</button>':''}<h3>Historial del caso</h3><ol class="timeline">${c.historial.map(h=>`<li><small>${esc(Modelo.persona(h.autor)?.nombre||h.autor)} · ${esc(h.estado)}</small><time>${esc(new Date(h.fecha).toLocaleString('es-CO'))}</time><p>${esc(h.texto)}</p></li>`).join('')}</ol><div id="case-actions"></div>${action('solicitudes','Volver a solicitudes')}`);if(c.documento)$('download').onclick=()=>download(c.documento,c.id);if(!active(c))return;
  if(gestor()||c.estado==='Esperando información'){const states=gestor()?['En atención','Esperando información',...(c.tipo==='Vacaciones'?['Aprobada','Devuelta']:['Resuelto'])]:['Recibido'];$('case-actions').innerHTML='<form id="reply"><label for="reply-text">'+(gestor()?'Respuesta al colaborador':'Información solicitada')+'</label><textarea id="reply-text" rows="3" required maxlength="1500"></textarea><label for="reply-state">Estado al enviar</label><select id="reply-state">'+options(states)+'</select><button class="primary">Enviar respuesta</button></form>';$('reply').onsubmit=e=>{e.preventDefault();const text=$('reply-text').value,status=$('reply-state').value;mutate(s=>Modelo.actualizarCaso(s,p.id,id,status,text),()=>caseView(id));};}
  if(!gestor()){$('case-actions').insertAdjacentHTML('beforeend','<button id="cancel-case" class="chip">Cancelar solicitud</button>');$('cancel-case').onclick=()=>{show('¿Cancelar esta solicitud?','<p>Se conservará el historial y se liberarán los días reservados, si aplica.</p><button id="confirm-cancel" class="primary">Sí, cancelar solicitud</button>'+action('caso/'+id,'Volver al caso'));$('confirm-cancel').onclick=()=>mutate(s=>Modelo.actualizarCaso(s,p.id,id,'Cancelada','Cancelada por el colaborador.'),()=>caseView(id));};}
}
function contentsView(){if(!gestor())return show('Acceso de Gestión Humana','<p>Selecciona el perfil de Laura para administrar contenidos en la demo.</p>');show('Conocimiento que mejora','<p>Los borradores no se muestran a los colaboradores. Publicar actualiza la versión. Los contenidos siguen pendientes de validación real.</p>'+state.articulos.map(a=>`<article class="entry"><b>${esc(a.titulo)}</b><p>${esc(a.responsable)} · v${a.version} · ${state.borradores[a.id]?'Borrador guardado':'Publicado'} · ${state.feedback.filter(f=>f.articulo===a.id&&!f.util).length} solicitudes de ayuda</p>${action('editar/'+a.id,'Editar contenido')}</article>`).join(''));}
function editView(id){if(!gestor())return contentsView();const a=state.articulos.find(a=>a.id===id);if(!a)return contentsView();const draft=state.borradores[id]||a,fields=[['titulo','Pregunta'],['respuesta','Respuesta'],['requisitos','Requisitos'],['pasos','Pasos (uno por línea)'],['fuente','Fuente de referencia']];show('Editar respuesta',`<p>Versión publicada: ${a.version}. La publicación solo afecta esta demo.</p><form id="edit-content">${fields.map(([key,label])=>`<label for="field-${key}">${label}</label><textarea id="field-${key}" rows="${key==='respuesta'?4:2}" required maxlength="3000">${esc(draft[key])}</textarea>`).join('')}<label for="audience">Audiencia</label><select id="audience"><option value="todos">Todos</option><option value="admin">Administración</option><option value="produccion">Producción</option></select><label for="owner">Responsable</label><select id="owner">${options(['Gestión Humana','Nómina','Contratación','SST'])}</select><button class="chip" value="draft">Guardar borrador</button><button class="primary" value="publish">Publicar versión</button></form>${action('contenidos','Volver a contenidos')}`);$('audience').value=draft.audiencia;$('owner').value=draft.responsable;
  $('edit-content').onsubmit=e=>{e.preventDefault();const publish=e.submitter.value==='publish',data=Object.fromEntries(fields.map(([key])=>[key,$('field-'+key).value.trim()]));data.audiencia=$('audience').value;data.responsable=$('owner').value;mutate(s=>{if(s.articulos.find(x=>x.id===id).version!==a.version)throw new Error('Hay una versión más reciente. Vuelve a abrir el contenido.');s.borradores[id]=data;if(publish)Modelo.publicar(s,id,p.id);},()=>{go('contenidos');notice(publish?'Nueva versión publicada en la demo.':'Borrador guardado. La respuesta publicada sigue disponible.');});};}
function routePage(){const [route,id]=location.hash.slice(1).split('/');const pages={vacaciones:()=>vacation(),prediccion:forecast,nomina:payroll,certificado:certificate,solicitudes:historyView,ayuda:()=>helpView(id),articulo:()=>articleView(id),caso:()=>caseView(id),contenidos:contentsView,editar:()=>editView(id),saldo:()=>articleView('saldo'),dotacion:()=>articleView('dotacion'),ergonomia:()=>articleView('ergonomia')};if(Object.hasOwn(pages,route))pages[route]();else{if(modal.open)modal.close();if(route==='preguntas')$('preguntas').scrollIntoView();}}
$('perfil').onchange=()=>{p=Modelo.persona($('perfil').value);try{localStorage.setItem('perfil-demo',p.id);}catch{notice('No se pudo guardar el perfil.');}$('query').value='';render();go('inicio');};
$('faq-filter').onchange=renderFAQ;$('query').oninput=suggestions;$('query').onkeydown=e=>{if(e.key==='Enter'&&!/ausentar|faltar/i.test($('query').value))$('matches').querySelector('button')?.click();};document.addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)go(b.dataset.route);});$('close').onclick=()=>go('inicio');modal.addEventListener('cancel',()=>go('inicio'));window.addEventListener('hashchange',routePage);
window.addEventListener('storage',e=>{if(e.key===Modelo.clave){try{state=Modelo.leer();render();notice('Los datos se actualizaron desde otra pestaña. Reabre el caso para ver su estado más reciente.');}catch(err){notice(err.message);}}});
$('reset').onclick=()=>{show('¿Restablecer la demostración?','<p>Se eliminarán los casos, borradores y valoraciones de esta versión en este navegador. Volverán los ejemplos iniciales.</p><button class="primary" id="confirm-reset">Restablecer datos ficticios</button>');$('confirm-reset').onclick=async()=>{try{const reset=()=>{state=Modelo.inicial();localStorage.setItem(Modelo.clave,JSON.stringify(state));};if(navigator.locks)await navigator.locks.request(Modelo.clave,reset);else reset();render();go('inicio');notice('Demostración restablecida.');}catch(e){$('form-error').textContent=e.message;}};};
render();routePage();if(bootError)notice(bootError);
